#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const childProcess = require('child_process');
const os = require('os');

const version = '1.0.2';

function getArgValue(name) {
  const index = process.argv.indexOf(name);
  if (index < 0) return undefined;
  return process.argv[index + 1];
}

function printHelp() {
  console.log(`Cursor 中文增强补丁 v${version}

用法:
  node patch-cursor-zh.js
  node patch-cursor-zh.js --backup
  node patch-cursor-zh.js --app /Applications/Cursor.app

参数:
  --app <path>          指定 Cursor.app 路径，默认 /Applications/Cursor.app
  --app-root <path>     指定 Cursor 资源目录，通常不需要手动设置
  --backup             写入前生成备份文件
  --no-user-storage    跳过用户配置数据库中的模式名称/思考强度修正
  -h, --help           显示帮助
  -v, --version        显示版本

环境变量:
  CURSOR_APP_ROOT=/path/to/app/resources
  CURSOR_LOCALIZER_BACKUP=1

说明:
  运行前请完全退出 Cursor。Cursor 更新或重装后，需要重新运行本补丁。
`);
}

if (process.argv.includes('--help') || process.argv.includes('-h')) {
  printHelp();
  process.exit(0);
}

if (process.argv.includes('--version') || process.argv.includes('-v')) {
  console.log(version);
  process.exit(0);
}

function resolveAppRoot(input) {
  const target = input || '/Applications/Cursor.app';
  const resolved = path.resolve(target);
  if (resolved.endsWith('.app')) return path.join(resolved, 'Contents/Resources/app');
  return resolved;
}

const appRoot = resolveAppRoot(getArgValue('--app-root') || getArgValue('--app') || process.env.CURSOR_APP_ROOT);
