function replaceFunctionRange(input, entry) {
  const start = input.indexOf(entry.startToken);
  if (start < 0) return { text: input, changed: false };
  const end = input.indexOf(entry.endToken, start + entry.startToken.length);
  if (end < 0) return { text: input, changed: false };
  const before = input.slice(start, end);
  if (before === entry.replacement) return { text: input, changed: false };
  return {
    text: input.slice(0, start) + entry.replacement + input.slice(end),
    changed: true,
  };
}

function applyWorkbenchTargetedTransforms(input) {
  let text = input;
  const applied = [];

  for (const entry of workbenchFunctionReplacements) {
    const result = replaceFunctionRange(text, entry);
    if (result.changed) {
      text = result.text;
      applied.push(entry.label);
    }
  }

  for (const [from, to] of workbenchTargetedReplacements) {
    const count = text.split(from).length - 1;
    if (count > 0) {
      text = replaceAllLiteral(text, from, to);
      applied.push(`${count}x ${from.slice(0, 80)}`);
    }
  }

  return { text, applied };
}

function patchWorkbench() {
  if (!fs.existsSync(workbenchFile)) {
    console.error(`Cursor workbench file not found: ${workbenchFile}`);
    process.exit(1);
  }

  let text = fs.readFileSync(workbenchFile, 'utf8');
  if (text.includes(marker)) {
    console.log('Cursor localizer already applied; checking for missed replacements.');
  }

  const results = [];
  const skipped = [];
  let changed = false;
  for (const [from, to] of replacements) {
    if (from === to) {
      skipped.push(from);
      continue;
    }
    const before = text.split(from).length - 1;
    if (before > 0) {
      text = replaceAllLiteral(text, from, to);
      changed = true;
    }
    results.push({ from, count: before });
  }

  const targeted = applyWorkbenchTargetedTransforms(text);
  if (targeted.applied.length > 0) {
    text = targeted.text;
    changed = true;
  }

  if (!text.includes(marker)) {
    text = `${marker}\n${text}`;
    changed = true;
  }

  if (changed) {
    const backup = backupFile(workbenchFile);
    fs.writeFileSync(workbenchFile, text);
    console.log(`Patched workbench: ${workbenchFile}`);
    if (backup) console.log(`Backup: ${backup}`);
    else console.log('Backup: skipped (set CURSOR_LOCALIZER_BACKUP=1 to enable)');
  } else {
    console.log('No workbench changes needed.');
  }

  const hit = results.filter((item) => item.count > 0);
  const miss = results.filter((item) => item.count === 0);
  console.log(`Applied workbench replacement entries: ${hit.length}/${results.length}`);
  for (const item of hit) console.log(`  ${item.count}x ${item.from.slice(0, 100)}`);
  if (skipped.length) console.log(`Skipped no-op replacement entries: ${skipped.length}`);
  if (targeted.applied.length) {
    console.log(`Applied targeted workbench transforms: ${targeted.applied.length}`);
    for (const item of targeted.applied) console.log(`  ${item}`);
  }
  if (miss.length) {
    console.log(`Missed workbench replacement entries: ${miss.length}`);
    for (const item of miss) console.log(`  0x ${item.from.slice(0, 100)}`);
  }
}

function getConfigList(pkg) {
  const configuration = pkg.contributes && pkg.contributes.configuration;
  if (!configuration) return [];
  return Array.isArray(configuration) ? configuration : [configuration];
}

function patchJson(relativePath, update) {
  const file = path.join(appRoot, relativePath);
  if (!fs.existsSync(file)) {
    console.log(`Skip missing JSON: ${file}`);
    return false;
  }

  const before = fs.readFileSync(file, 'utf8');
  const json = JSON.parse(before);
  update(json);
  const after = `${JSON.stringify(json, null, 2)}\n`;
  if (after === before) {
    console.log(`No JSON changes needed: ${file}`);
    return false;
  }

  const backup = backupFile(file);
  fs.writeFileSync(file, after);
  console.log(`Patched JSON: ${file}`);
  if (backup) console.log(`Backup: ${backup}`);
  else console.log('Backup: skipped (set CURSOR_LOCALIZER_BACKUP=1 to enable)');
  return true;
}

function patchText(relativePath, entries) {
  const file = path.join(appRoot, relativePath);
  return patchTextFile(file, entries, relativePath);
}

function patchTextFile(file, entries, label = file) {
  if (!fs.existsSync(file)) {
    console.log(`Skip missing text: ${file}`);
    return false;
  }

  let text = fs.readFileSync(file, 'utf8');
  const results = [];
  let changed = false;
  for (const [from, to] of entries) {
    if (from === to) {
      results.push({ from, count: 0, skipped: true });
      continue;
    }
    const count = text.split(from).length - 1;
    if (count > 0) {
      text = replaceAllLiteral(text, from, to);
      changed = true;
    }
    results.push({ from, count, skipped: false });
  }

  if (!changed) {
    console.log(`No text changes needed: ${file}`);
  } else {
    const backup = backupFile(file);
    fs.writeFileSync(file, text);
    console.log(`Patched text: ${file}`);
    if (backup) console.log(`Backup: ${backup}`);
    else console.log('Backup: skipped (set CURSOR_LOCALIZER_BACKUP=1 to enable)');
  }

  const hit = results.filter((item) => item.count > 0);
  console.log(`Applied text replacement entries for ${label}: ${hit.length}/${results.length}`);
  for (const item of hit) console.log(`  ${item.count}x ${item.from.slice(0, 100)}`);
  return changed;
}

