function getCursorLanguageCacheFiles() {
  const root = path.join(os.homedir(), 'Library/Application Support/Cursor/clp');
  if (!fs.existsSync(root)) return [];

  const files = [];
  const stack = [root];
  while (stack.length) {
    const dir = stack.pop();
    let entries;
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      continue;
    }

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        stack.push(fullPath);
      } else if (entry.isFile() && entry.name === 'nls.messages.json') {
        files.push(fullPath);
      }
    }
  }

  return files.sort();
}

