function isCursorAppRunning() {
  try {
    const output = childProcess.execFileSync('ps', ['-axo', 'args='], { encoding: 'utf8' });
    return output.split('\n').some((line) => line.includes('/Applications/Cursor.app/Contents/MacOS/Cursor'));
  } catch (error) {
    console.log(`Could not check Cursor process state: ${error.message}`);
    return true;
  }
}

function sqliteQuote(value) {
  return `'${String(value).replace(/'/g, "''")}'`;
}

function patchReasoningDefinitions(value) {
  const setEnumDisplayNames = (node, namesByValue) => {
    const values = node.parameterType?.enumParameter?.values;
    if (!Array.isArray(values)) return;
    for (const option of values) {
      if (!option || typeof option !== 'object') continue;
      const key = String(option.value ?? option.displayName ?? '').toLowerCase();
      if (Object.prototype.hasOwnProperty.call(namesByValue, key)) {
        option.displayName = namesByValue[key];
      }
    }
  };

  const visit = (node) => {
    if (!node || typeof node !== 'object') return;
    if (Array.isArray(node)) {
      for (const item of node) visit(item);
      return;
    }

    if (node.id === 'reasoning') {
      if (node.name === 'Reasoning') node.name = '思考强度';
      if (node.markdownTooltip === 'Controls how much reasoning effort the model uses.') {
        node.markdownTooltip = '控制模型使用多少思考强度。';
      }
      const values = node.parameterType?.enumParameter?.values;
      if (Array.isArray(values)) {
        for (const option of values) {
          if (!option || typeof option !== 'object') continue;
          const key = String(option.value ?? option.displayName ?? '').toLowerCase();
          if (key === 'none') option.displayName = 'None';
          else if (key === 'minimal') option.displayName = 'Minimal';
          else if (key === 'low') option.displayName = 'Low';
          else if (key === 'medium') option.displayName = 'Medium';
          else if (key === 'high') option.displayName = 'High';
          else if (key === 'xhigh' || key === 'extra high') option.displayName = 'Extra High';
        }
      }
    } else if (node.id === 'thinking') {
      if (node.name === 'Thinking') node.name = '扩展思考';
      if (
        node.markdownTooltip === 'Enable extended thinking' ||
        node.markdownTooltip === 'Enable extended thinking for complex reasoning' ||
        node.markdownTooltip === 'Enable extended thinking for complex reasoning tasks'
      ) {
        node.markdownTooltip = '启用扩展思考，用于复杂推理';
      }
    } else if (node.id === 'effort') {
      if (node.name === 'Effort') node.name = '思考强度';
      setEnumDisplayNames(node, {
        low: 'Low',
        medium: 'Medium',
        high: 'High',
        xhigh: 'Extra High',
        max: 'Max',
      });
    } else if (node.id === 'context') {
      if (node.name === 'Context') node.name = '上下文';
      if (node.markdownTooltip === 'Maximum context window size') {
        node.markdownTooltip = '最大上下文窗口大小';
      }
    }

    for (const item of Object.values(node)) visit(item);
  };

  visit(value);
}

function patchUserPersistentStorage() {
  const dbFile = path.join(os.homedir(), 'Library/Application Support/Cursor/User/globalStorage/state.vscdb');
  const storageKey = 'src.vs.platform.reactivestorage.browser.reactiveStorageServiceImpl.persistentStorage.applicationUser';

  if (!fs.existsSync(dbFile)) {
    console.log(`Skip missing Cursor user storage: ${dbFile}`);
    return;
  }

  if (isCursorAppRunning()) {
    console.log('Skip Cursor user storage patch: Cursor is currently running. Quit Cursor completely, then run this script again.');
    return;
  }

  const before = childProcess.execFileSync('sqlite3', [
    dbFile,
    `SELECT value FROM ItemTable WHERE key=${sqliteQuote(storageKey)};`,
  ], { encoding: 'utf8', maxBuffer: 50 * 1024 * 1024 });
  if (!before.trim()) {
    console.log('Skip Cursor user storage patch: applicationUser storage row not found.');
    return;
  }

  const data = JSON.parse(before);
  const modeTranslations = {
    agent: ['智能体', '规划、搜索、修改文件并运行命令'],
    plan: ['计划', '为任务制定详细计划'],
    chat: ['对话', '与 Cursor 对话，询问你的代码库'],
    triage: ['分诊', '协调长期任务，并委派给子智能体'],
    spec: ['规格', '制定包含实施步骤的结构化计划'],
    debug: ['调试', '根据运行过程记录系统排查并修复问题'],
    multitask: ['多任务', '并行运行并协调多个任务'],
    project: ['项目', '用于项目级讨论的特殊对话模式'],
  };

  const modes = data.composerState?.modes4;
  if (Array.isArray(modes)) {
    for (const mode of modes) {
      const translation = modeTranslations[mode.id];
      if (!translation) continue;
      mode.name = translation[0];
      mode.description = translation[1];
    }
  }

  patchReasoningDefinitions(data);

  const after = JSON.stringify(data);
  if (after === before.trim()) {
    console.log('No Cursor user storage changes needed.');
    return;
  }

  childProcess.execFileSync('sqlite3', [
    dbFile,
    `UPDATE ItemTable SET value=${sqliteQuote(after)} WHERE key=${sqliteQuote(storageKey)};`,
  ]);
  console.log(`Patched Cursor user storage: ${dbFile}`);
}

function sha256Base64NoPadding(file) {
  return crypto.createHash('sha256').update(fs.readFileSync(file)).digest('base64').replace(/=+$/, '');
}

function patchProductChecksums() {
  patchJson('product.json', (product) => {
    const checksums = product.checksums || {};
    let updated = 0;

    for (const relativePath of Object.keys(checksums)) {
      const file = path.join(appRoot, 'out', relativePath);
      if (!fs.existsSync(file)) {
        console.log(`Skip missing checksum target: ${file}`);
        continue;
      }

      const actual = sha256Base64NoPadding(file);
      if (checksums[relativePath] !== actual) {
        checksums[relativePath] = actual;
        updated += 1;
      }
    }

    product.checksums = checksums;
    console.log(`Updated product checksums: ${updated}`);
  });
}

function patchCursorExtensionPackages() {
  patchJson('extensions/cursor-ndjson-ingest/package.json', (pkg) => {
    pkg.displayName = 'Cursor NDJSON 日志导入';
    pkg.description = '把 NDJSON 日志写入 workspace/.cursor/debug.log 的本地 HTTP 服务';
    const commandTitles = {
      'cursor.ndjsonIngest.start': 'Cursor NDJSON 日志导入：启动服务',
      'cursor.ndjsonIngest.stop': 'Cursor NDJSON 日志导入：停止服务',
      'cursor.ndjsonIngest.copyCurl': 'Cursor NDJSON 日志导入：复制 curl 命令',
      'cursor.ndjsonIngest.reassignPort': 'Cursor NDJSON 日志导入：重新分配端口并重启服务',
      'cursor.ndjsonIngest.showStatus': 'Cursor NDJSON 日志导入：显示服务信息',
    };
    for (const command of pkg.contributes?.commands || []) {
      if (commandTitles[command.command]) command.title = commandTitles[command.command];
    }
    for (const cfg of getConfigList(pkg)) {
      if (cfg.title === 'NDJSON Ingest') cfg.title = 'NDJSON 日志导入';
      const props = cfg.properties || {};
      if (props['ndjson.port']) props['ndjson.port'].description = 'NDJSON 日志导入服务端口。设为 0 时，会在 7242-7942 范围内自动分配。';
      if (props['ndjson.bindAddress']) {
        props['ndjson.bindAddress'].description = 'NDJSON 日志导入服务绑定的地址。\n警告：设为非本机地址（例如 0.0.0.0）会把此端点暴露到外部网络，可能允许远程访问日志导入端点，存在风险。';
      }
    }
  });

  patchJson('extensions/cursor-retrieval/package.json', (pkg) => {
    pkg.description = '处理 Cursor 的代码索引与检索';
    for (const cfg of getConfigList(pkg)) {
      if (cfg.title === 'Cursor Retrieval') cfg.title = 'Cursor 检索';
      const props = cfg.properties || {};
      if (props['cursor-retrieval.canAttemptGithubLogin']) {
        props['cursor-retrieval.canAttemptGithubLogin'].description = '是否允许 Cursor 尝试登录 GitHub，以增强检索结果。';
      }
    }
  });

  patchJson('extensions/cursor-always-local/package.json', (pkg) => {
    pkg.description = 'Cursor 实验功能组件';
    for (const cfg of getConfigList(pkg)) {
      if (cfg.title === 'Cursor Always Local') cfg.title = 'Cursor 始终本地';
    }
  });

  patchJson('extensions/cursor-shadow-workspace/package.nls.json', (pkg) => {
    pkg.displayName = 'Cursor 影子工作区';
    pkg.description = '管理一个隐藏的本地窗口，AI 智能体可以先在其中打磨代码，再展示给你。';
  });

  patchJson('extensions/cursor2plus/package.json', (pkg) => {
    pkg.description = 'Cursor++ BYOK 扩展：为 Cursor IDE 使用你自己的密钥';
    for (const cfg of getConfigList(pkg)) {
      const props = cfg.properties || {};
      if (props['cursor2plus.server.host']) props['cursor2plus.server.host'].description = 'BYOK 服务监听地址';
      if (props['cursor2plus.server.port']) props['cursor2plus.server.port'].description = 'BYOK 服务监听端口';
      if (props['cursor2plus.server.autoStart']) props['cursor2plus.server.autoStart'].description = '扩展激活时自动启动 BYOK 服务';
      if (props['cursor2plus.collector.port']) props['cursor2plus.collector.port'].description = 'Hook 收集器端口（设为 0 时合并到 BYOK 服务）';
    }
  });
}

console.log(`Cursor 中文增强补丁 v${version}`);
